const labels: Record<string, readonly [string, string]> = {
  en: ["item", "items"],
  fr: ["article", "articles"],
  es: ["artículo", "artículos"],
};

export function formatItemCount(count: number, locale: string): string {
  const language = locale.toLowerCase().split("-")[0];
  const [singular, plural] = labels[language] ?? labels.en;
  const form = new Intl.PluralRules(locale).select(count) === "one" ? singular : plural;
  return `${count} ${form}`;
}

