function debounce(callback, delay) {
  let timer;
  let firstArgs;

  return function (...args) {
    const context = this;
    if (!timer) firstArgs = args;
    clearTimeout(timer);
    timer = setTimeout(() => {
      callback.apply(context, firstArgs);
      timer = null;
    }, delay);
  };
}

module.exports = debounce;
