package roadside;

import java.util.Arrays;
import java.util.List;

public final class Flags {
    public static final class DriverRecord {
        public final String id;
        public final double bac;
        public boolean flagged;

        public DriverRecord(String id, double bac) {
            this.id = id;
            this.bac = bac;
        }
    }

    public static void markOutsideReferenceRange(List<DriverRecord> records, double lower, double upper) {
        for (DriverRecord driver : records) {
            driver.flagged = driver.bac < lower || driver.bac > upper;
        }
    }

    public static void main(String[] args) {
        List<DriverRecord> records = Arrays.asList(
                new DriverRecord("R12", 0.02),
                new DriverRecord("M07", 0.081),
                new DriverRecord("Q31", 0.00),
                new DriverRecord("T44", 0.085));
        markOutsideReferenceRange(records, 0.00, 0.08);
        for (DriverRecord driver : records) {
            System.out.println(driver.id + ":" + driver.flagged);
        }
    }
}

