export type CartAction =
  | { type: "cart/itemAdded"; id: string }
  | { type: "cart/itemRemoved"; id: string }
  | { type: "cart/cleared" };

export type CartState = { items: string[] };

const initialState: CartState = { items: [] };

export function cartReducer(
  state: CartState = initialState,
  action: CartAction
): CartState {
  if (action.type === "cart/itemAdded") {
    return { ...state, items: [...state.items, action.id] };
  } else if (action.type === "cart/itemRemoved") {
    return { ...state, items: state.items.filter((id) => id !== action.id) };
  } else if (action.type === "cart/cleared") {
    return { ...state, items: [] };
  }
  return state;
}
