import time

class TTLCache:
    def __init__(self):
        self._items = {}

    def put(self, key, value, ttl):
        self._items[key] = (value, time.time() + ttl)

    def get(self, key):
        entry = self._items.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if time.time() >= expires_at:
            del self._items[key]
            return None
        return value

