package pool

type Job func()

type Pool struct {
	jobs    chan Job
	done    chan struct{}
	workers int
}

func New(workers int) *Pool {
	p := &Pool{jobs: make(chan Job), done: make(chan struct{}), workers: workers}
	for i := 0; i < workers; i++ {
		go p.work()
	}
	return p
}

func (p *Pool) Submit(job Job) {
	p.jobs <- job
}

func (p *Pool) Close() {
	close(p.jobs)
	for i := 0; i < p.workers; i++ {
		<-p.done
	}
}

func (p *Pool) work() {
	for {
		job := <-p.jobs
		if job == nil {
			continue
		}
		job()
	}
	p.done <- struct{}{}
}

