func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: protolist DIR")
		os.Exit(2)
	}

	root := os.Args[1]
	var paths []string
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if !entry.IsDir() && filepath.Ext(path) == ".proto" {
			paths = append(paths, path)
		}
		return nil
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	sort.Strings(paths)
	for _, path := range paths {
		fmt.Println(path)
	}
}

