import java.util.Arrays;

public class Scheduler {
    public static int maxBookings(int[][] bookings) {
        int[][] ordered = Arrays.stream(bookings)
                .map(int[]::clone)
                .toArray(int[][]::new);
        Arrays.sort(ordered, (a, b) -> Integer.compare(a[1], b[1]));
        int count = 0;
        int lastFinish = Integer.MIN_VALUE;
        for (int[] booking : ordered) {
            if (booking[0] >= lastFinish) {
                count++;
                lastFinish = booking[1];
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[][] bookings = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {8, 9}, {5, 9}};
        System.out.println(maxBookings(bookings));
    }
}

